import * as THREE from 'three/webgpu';
import { texture, uv, mix, float, vec3, color, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'brand-mark-wall';

  const pos = config.scenePosition?.position || [0, 0, 0];
  const rot = config.scenePosition?.rotation || [0, 0, 0];
  const scl = config.scenePosition?.scale || [1, 1, 1];
  group.position.set(...pos);
  group.rotation.set(...rot);
  group.scale.set(...scl);

  const brandNames = ['HODINKEE', 'MONOCLE', 'WALLPAPER', 'ESQUIRE', 'WIRED', 'FINANCIAL TIMES'];

  const tileW = 1.0;
  const tileH = 0.62;
  const gap = 0.25;
  const cols = 3;
  const rows = 2;
  const gridW = cols * tileW + (cols - 1) * gap;
  const gridH = rows * tileH + (rows - 1) * gap;

  const startX = -gridW / 2 + tileW / 2;
  const startY = gridH / 2 - tileH / 2;

  const disposables = [];
  const timelines = [];
  const tiles = [];

  // Kicker text
  const kicker = createTextMesh({
    text: 'AS FEATURED IN',
    font: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 0.09,
    letterSpacing: 0.12,
    lineHeight: 1.2,
    color: '#e8ecf2',
    align: 'center',
    fontAtlas: ctx.fontAtlas
  });
  kicker.position.set(0, gridH / 2 + 0.3, 0.03);
  group.add(kicker);
  disposables.push(kicker);

  const geometry = new THREE.BoxGeometry(tileW, tileH, 0.06, 1, 1, 1);
  disposables.push(geometry);

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const x = startX + c * (tileW + gap);
      const y = startY - r * (tileH + gap);

      const colorTop = color('#1a1a22');
      const colorBottom = color('#121218');
      const vUv = uv();
      const albedo = mix(colorTop, colorBottom, vUv.y);

      const material = new THREE.MeshStandardNodeMaterial();
      material.colorNode = albedo;
      material.roughness = 0.55;
      material.metalness = 0.5;
      material.clearcoat = 0.2;
      material.clearcoatRoughness = 0.3;
      material.anisotropy = 0.6;
      material.anisotropyRotation = 0;

      const tile = new THREE.Mesh(geometry, material);
      tile.position.set(x, y, 0);
      tile.castShadow = false;
      tile.receiveShadow = false;
      tile.userData.baseZ = 0;
      tile.userData.baseY = y;

      const brandMesh = createTextMesh({
        text: brandNames[idx],
        font: 'JetBrains Mono',
        fontWeight: 700,
        fontSize: 0.13,
        letterSpacing: 0.08,
        lineHeight: 1,
        color: '#e8ecf2',
        align: 'center',
        fontAtlas: ctx.fontAtlas
      });
      brandMesh.position.set(0, 0, 0.035);
      brandMesh.userData.baseOpacity = 0.78;

      if (brandMesh.material) {
        brandMesh.material.transparent = true;
        brandMesh.material.opacity = 0.78;
      } else {
        brandMesh.traverse((child) => {
          if (child.material) {
            child.material.transparent = true;
            child.material.opacity = 0.78;
          }
        });
      }

      tile.add(brandMesh);
      tile.userData.brandMesh = brandMesh;

      group.add(tile);
      tiles.push(tile);
      disposables.push(material, brandMesh);
    }
  }

  // Mount animation: stagger-cards / fade-up, top row left-to-right first
  tiles.forEach((tile, i) => {
    tile.position.y = tile.userData.baseY + 0.2;
    if (tile.userData.brandMesh) {
      if (tile.userData.brandMesh.material) {
        tile.userData.brandMesh.material.opacity = 0;
      }
    }
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(tile.position, {
      y: tile.userData.baseY,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
    }, 0);
    if (tile.userData.brandMesh?.material) {
      tl.to(tile.userData.brandMesh.material, {
        opacity: 0.78,
        duration: 0.5,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
      }, 0);
    }
    timelines.push(tl);
  });

  // Hover handlers
  group.userData.handlers = {
    onPointerOver: (event) => {
      const tile = event?.object;
      if (!tile || !tiles.includes(tile)) return;
      const tl = gsap.timeline();
      tl.to(tile.position, { z: 0.05, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
      if (tile.userData.brandMesh?.material) {
        tl.to(tile.userData.brandMesh.material, { opacity: 1.0, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
      }
      timelines.push(tl);
    },
    onPointerOut: (event) => {
      const tile = event?.object;
      if (!tile || !tiles.includes(tile)) return;
      const tl = gsap.timeline();
      tl.to(tile.position, { z: 0, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
      if (tile.userData.brandMesh?.material) {
        tl.to(tile.userData.brandMesh.material, { opacity: 0.78, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
      }
      timelines.push(tl);
    }
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    disposables.forEach((obj) => {
      if (obj?.geometry?.dispose) obj.geometry.dispose();
      if (obj?.material?.dispose) obj.material.dispose();
      if (obj?.dispose) obj.dispose();
    });
    group.traverse((child) => {
      if (child.geometry?.dispose) child.geometry.dispose();
      if (child.material?.dispose) child.material.dispose();
    });
  };

  return group;
}
